#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: run this on the Raspberry Pi itself, as the user the runners should
# run as (not root). See "Where it runs" in docs/archive.md and issue #24.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

REPO="corinbz/mealdeal"
export GH_REPO="$REPO"
LABEL="pi"
RUNNER_VAR='["self-hosted","pi"]'

have_gh() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }

banner "Run the daily archive on this Raspberry Pi"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check this machine"
if [[ $EUID -eq 0 ]]; then
  warn "Run this as your normal user, not root: the runner refuses to run as root."
  exit 1
fi
arch=$(dpkg --print-architecture 2>/dev/null || uname -m)
if [[ "$arch" != "arm64" && "$arch" != "aarch64" ]]; then
  warn "This system is '$arch'. The runner needs a 64-bit OS (arm64)."
  say "Reflash with Raspberry Pi OS Lite (64-bit) and run this again."
  exit 1
fi
printf '  %s✓%s 64-bit (%s), running as %s\n' "$GREEN" "$RESET" "$arch" "$USER"
say "The archive runs at 04:30 UTC every day, so this Pi must be on and online then."
note "If it is off, the morning check at 08:00 UTC goes red and GitHub emails you."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Install what the archive job needs"
say "git, curl, jq and unzip from apt, and the AWS CLI, which talks to R2."
note "Node is not installed here: the job's setup-node step fetches it itself."
if confirm "Install them now with sudo?"; then
  sudo apt-get update -qq
  sudo apt-get install -y -qq git curl jq unzip
  if command -v aws >/dev/null 2>&1; then
    printf '  %s✓%s AWS CLI already installed: %s\n' "$GREEN" "$RESET" "$(aws --version)"
  else
    tmp=$(mktemp -d)
    curl -fsSL "https://awscli.amazonaws.com/awscli-exe-linux-aarch64.zip" -o "$tmp/awscliv2.zip"
    unzip -q "$tmp/awscliv2.zip" -d "$tmp"
    sudo "$tmp/aws/install"
    rm -rf "$tmp"
    printf '  %s✓%s installed %s\n' "$GREEN" "$RESET" "$(aws --version)"
  fi
else
  SKIPPED+=("install git curl jq unzip and the AWS CLI (arm64)")
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Get a runner registration token"
say "GitHub hands out a one-hour token to register runners with this repository."
if have_gh; then
  RUNNER_TOKEN=$(gh api -X POST "repos/$REPO/actions/runners/registration-token" --jq .token)
  printf '  %s✓%s got a token from gh\n' "$GREEN" "$RESET"
else
  note "gh is not signed in here, so take it from the page instead."
  open_url "https://github.com/$REPO/settings/actions/runners/new?arch=arm64&os=linux"
  step "Under Configure, find the line starting ./config.sh --url ... --token"
  step "Copy only the value after --token."
  ask_secret RUNNER_TOKEN "Paste the token:"
fi
if [[ -z "${RUNNER_TOKEN:-}" ]]; then
  warn "No token, so no runner can be registered. Run this again when you have one."
  exit 1
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Register the runners"
say "Each runner takes one job at a time, and each Chain is its own job."
say "One runner per Chain sweeps them in parallel: about an hour, not two."
ask RUNNER_COUNT "How many runners? [2]"
RUNNER_COUNT=${RUNNER_COUNT:-2}
version=$(curl -fsSL https://api.github.com/repos/actions/runner/releases/latest | jq -r .tag_name)
version=${version#v}
tarball="$HOME/actions-runner-linux-arm64-$version.tar.gz"
if [[ ! -f "$tarball" ]]; then
  curl -fsSL "https://github.com/actions/runner/releases/download/v$version/actions-runner-linux-arm64-$version.tar.gz" -o "$tarball"
fi
for i in $(seq 1 "$RUNNER_COUNT"); do
  dir="$HOME/actions-runner-$i"
  name="$(hostname)-$i"
  if [[ -f "$dir/.runner" ]]; then
    printf '  %s✓%s %s is already registered, in %s\n' "$GREEN" "$RESET" "$name" "$dir"
    continue
  fi
  mkdir -p "$dir"
  tar -xzf "$tarball" -C "$dir"
  # The runner is a .NET program; this installs the libraries it links against.
  (cd "$dir" && sudo ./bin/installdependencies.sh >/dev/null)
  (cd "$dir" && ./config.sh --unattended --replace \
    --url "https://github.com/$REPO" --token "$RUNNER_TOKEN" \
    --name "$name" --labels "$LABEL" --work _work)
  # A service starts at boot, so a reboot or power cut does not need you.
  (cd "$dir" && sudo ./svc.sh install "$USER" && sudo ./svc.sh start)
  printf '  %s✓%s registered %s as a service\n' "$GREEN" "$RESET" "$name"
done
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Check GitHub sees the runners"
if have_gh; then
  gh api "repos/$REPO/actions/runners" \
    --jq '.runners[] | "  \(.name): \(.status), labels \([.labels[].name] | join(","))"'
  say "Each one should be online, with the label $LABEL."
else
  open_url "https://github.com/$REPO/settings/actions/runners"
  step "Each $(hostname)-N runner should be listed as Idle, with the label $LABEL."
fi
pause "Do they? Press Enter to continue, or Ctrl-C to stop and look."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Move the archive onto this Pi"
say "The archive workflow runs wherever the variable ARCHIVE_RUNNER says."
say "Setting it to $RUNNER_VAR moves every run here, the scheduled ones too."
note "To move back to GitHub's runners, delete it: gh variable delete ARCHIVE_RUNNER"
if confirm "Set ARCHIVE_RUNNER now?"; then
  set_var ARCHIVE_RUNNER "$RUNNER_VAR"
  if [[ " ${SKIPPED[*]} " == *"ARCHIVE_RUNNER"* ]]; then
    open_url "https://github.com/$REPO/settings/variables/actions/new"
    step "Name: ARCHIVE_RUNNER   Value: $RUNNER_VAR"
    pause "Press Enter once it is saved."
  fi
else
  SKIPPED+=("set the repository variable ARCHIVE_RUNNER to $RUNNER_VAR")
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Run the archive once on the Pi"
say "A full run of both Chains. On a day already archived it only restores"
say "what is in R2 and skips every step it has, so this is safe to run any time."
if confirm "Start it now?"; then
  if have_gh; then
    gh workflow run archive.yml -f chain=all
    sleep 5
    open_url "https://github.com/$REPO/actions/workflows/archive.yml"
  else
    open_url "https://github.com/$REPO/actions/workflows/archive.yml"
    step "Click Run workflow, choose Chain: all, and start it."
  fi
  step "Both jobs should say they ran on $(hostname)-1 and $(hostname)-2 and go green."
else
  SKIPPED+=("start a test run: gh workflow run archive.yml -f chain=all")
fi
pause

finish
